UPDATE lessons SET title='Year 3, Week 20, Lesson 1: People and places connected', data=json_patch(data,'{"child_mission":"People and places are connected through the things they share and trade, such as food, goods, jobs and ideas. A product passes through many places and people before it reaches us, so places depend on each other.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same HSIE idea to a new place or source, then compare two pieces of evidence for strength.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nBananas grown in Queensland can reach shops in other states. Write three steps in the chain from farm to your home.\n\nFEEDBACK\nFor example: grown and picked on a farm; packed and trucked to a market; delivered to a shop and bought. Name the places and people at each step.\n\nWATCH FOR\nBelieving food comes from the shop skips the farmers, truck drivers and workers who connect distant places.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nTrace one school lunch item back to where it was grown or made. Draw a chain with at least four links and name one person and one place for each link. Write what could go wrong if one link is cut.\n\nWrite a short reflection naming one source or idea you corrected and why.","interactive_activities":null,"learning_area":"HSIE","learning_intention":"People and places are connected through the things they share and trade, such as food, goods, jobs and ideas. A product passes through many places and people before it reaches us, so places depend on each other.","lesson_number":1,"lesson_role":"Investigate","materials":["Paper or typed answer space","Pencil","Optional: local map, photo or interview notes"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["HS2-GEO-01"],"parent_notes":"Parent: Marking guidance for the independent task: Trace one school lunch item back to where it was grown or made. Draw a chain with at least four links and name one person and one place for each link. Write what could go wrong if one link is cut. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original demonstration: Example: wheat grows on a farm, is trucked to a mill, becomes flour, is baked into bread at a bakery and is sold in a shop. Many people in different places each do one step. If a flood closes a road, the next step is delayed.\n\nParent: Written model 2: Common error: Believing food comes from the shop skips the farmers, truck drivers and workers who connect distant places. Correction: For example: grown and picked on a farm; packed and trucked to a market; delivered to a shop and bought. Name the places and people at each step.\n\nParent: Likely misconception: Believing food comes from the shop skips the farmers, truck drivers and workers who connect distant places. Keep sample answers out of the child role.","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"People and places are connected through the things they share and trade, such as food, goods, jobs and ideas. A product passes through many places and people before it reaches us, so places depend on each other. The other choices avoid explaining the actual strategy.","options":["People and places are connected through the things they share and trade, such as food, goods, jobs and ideas. A product passes through many places and people before it reaches us, so places depend on each other.","Believing food comes from the shop skips the farmers, truck drivers and workers who connect distant places.","Ignore the source and invent a more exciting story.","Copy the model places and call that independent work."],"question":"Which idea is taught in the stage \"Understand and model\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Make the HSIE idea visible: name the observation, source or example you used and say why it supports the claim. The other choices avoid explaining the actual strategy.","options":["Make the HSIE idea visible: name the observation, source or example you used and say why it supports the claim.","Writing only a final label without evidence does not show HSIE thinking.","Copy the model places and call that independent work.","Treat a missing fact as if it were recorded in a source."],"question":"Which idea is taught in the stage \"Show the evidence\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Use an intentionally incorrect claim as a comparison. Name its specific HSIE error, then show the corrected evidence-based claim. The other choices avoid explaining the actual strategy.","options":["Use an intentionally incorrect claim as a comparison. Name its specific HSIE error, then show the corrected evidence-based claim.","Changing the wording without repairing the evidence does not fix the error. Believing food comes from the shop skips the farmers, truck drivers and workers who connect distant places.","Treat a missing fact as if it were recorded in a source.","Skip respectful protocols because the first idea looked neat."],"question":"Which idea is taught in the stage \"Test a misconception\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"Use the same HSIE idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence. The other choices avoid explaining the actual strategy.","options":["Use the same HSIE idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence.","Repeating the worked example cannot show transfer to new evidence.","Skip respectful protocols because the first idea looked neat.","Ignore the source and invent a more exciting story."],"question":"Which idea is taught in the stage \"Transfer to a new inquiry\"?","type":"multiple_choice"},{"correct_index":0,"explanation":"For example: grown and picked on a farm; packed and trucked to a market; delivered to a shop and bought. Name the places and people at each step. Useful feedback uses the original sources and method.","options":["For example: grown and picked on a farm; packed and trucked to a market; delivered to a shop and bought. Name the places and people at each step.","Believing food comes from the shop skips the farmers, truck drivers and workers who connect distant places.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Bananas grown in Queensland can reach shops in other states. Write three steps i\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"The most useful record names the evidence and the reason it supports the claim, not only a label. Useful feedback uses the original sources and method.","options":["The most useful record names the evidence and the reason it supports the claim, not only a label.","Writing only a final label without evidence does not show HSIE thinking.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"List the key observations, sources or steps from the model and say what each one\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"For example: grown and picked on a farm; packed and trucked to a market; delivered to a shop and bought. Name the places and people at each step. Useful feedback uses the original sources and method.","options":["For example: grown and picked on a farm; packed and trucked to a market; delivered to a shop and bought. Name the places and people at each step.","Changing the wording without repairing the evidence does not fix the error. Believing food comes from the shop skips the farmers, truck drivers and workers who connect distant places.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Describe why the warned-against claim fails, then write a corrected claim with e\", which feedback is most useful?","type":"multiple_choice"},{"correct_index":0,"explanation":"The new example should use the same HSIE idea as the model, but contain different evidence. Useful feedback uses the original sources and method.","options":["The new example should use the same HSIE idea as the model, but contain different evidence.","Repeating the worked example cannot show transfer to new evidence.","Any answer is equally supported.","There is no need to compare your attempt."],"question":"After trying \"Inquire into or describe one fresh example that uses the same skill and write a \", which feedback is most useful?","type":"multiple_choice"},{"explanation":"Independent evidence, not repetition of the worked model, demonstrates the skill.","marking_guide":"Require independently produced relevant evidence with accurate reasoning and named sources or places.","question":"Inquire into or describe a fresh example that uses the central skill. Show evidence and name the sources or places that matter.","sample_answer":"Original demonstration: Example: wheat grows on a farm, is trucked to a mill, becomes flour, is baked into bread at a bakery and is sold in a shop. Many people in different places each do one step. If a flood closes a road, the next step is delayed.","type":"short_answer"},{"explanation":"A correction needs to change the claim or evidence, not just make the notes longer.","marking_guide":"Require an actual misconception plus corrected claim and an evidence-linked reason.","question":"Name one likely misconception for this HSIE topic, correct it and say why the correction works.","sample_answer":"Common error: Believing food comes from the shop skips the farmers, truck drivers and workers who connect distant places. Correction: For example: grown and picked on a farm; packed and trucked to a market; delivered to a shop and bought. Name the places and people at each step.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s2-hsie-y3-w20-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA HSIE alignment using catalogue outcome codes (HS2-*); content-point mapping and local First Nations protocols remain pending human review.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise connected.","Read the mission before you start mapping or using sources.","Keep the place, people or source you are studying in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your evidence with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the source or place detail that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore sources or respectful practice.","Prefer accurate evidence over a guess that merely looks neat."],"submit":["Confirm that your evidence and reason are both present.","Proofread names, places, dates and sequence.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact source detail or place feature before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key evidence.","Say what each source or place detail shows about the idea.","A final label alone is weaker than recorded evidence."],"teach2":["Compare a weak claim with stronger evidence.","Change the claim or use of sources, not only how neat the poster looks.","Name the mistake you are repairing."],"teach3":["Choose a fresh place, person or source that still uses the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original evidence and a short reason.","Save work that shows the skill on new sources or places."]},"subject":"Geography","success_criteria":["I can use connected with a specific example from this lesson.","I can identify supply and explain why it matters.","I can practise transport independently on a new prompt.","I can notice interdependence needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"People and places are connected through the things they share and trade, such as food, goods, jobs and ideas. A product passes through many places and people before it reaches us, so places depend on each other. Supported records follow the actual sources and purpose of the task.","options":["People and places are connected through the things they share and trade, such as food, goods, jobs and ideas. A product passes through many places and people before it reaches us, so places depend on each other.","A claim unrelated to the source or place.","An answer copied without understanding.","A guess with no evidence."],"question":"What should you demonstrate in this teaching stage?"},"example":"WORKED MODEL\nExample: wheat grows on a farm, is trucked to a mill, becomes flour, is baked into bread at a bakery and is sold in a shop. Many people in different places each do one step. If a flood closes a road, the next step is delayed.\n\nTRY FIRST\nBananas grown in Queensland can reach shops in other states. Write three steps in the chain from farm to your home.\n\nFEEDBACK\nFor example: grown and picked on a farm; packed and trucked to a market; delivered to a shop and bought. Name the places and people at each step.","explain":"People and places are connected through the things they share and trade, such as food, goods, jobs and ideas. A product passes through many places and people before it reaches us, so places depend on each other.\n\nWHY IT MATTERS\nThis helps the learner base claims on sources, places and respectful community knowledge, rather than guessing from a single picture. Keep every claim linked to evidence.\n\nHOW TO WORK\nRead the worked example and name the sources, map features or community examples that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a detail is uncertain, identify what source you would need next. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Believing food comes from the shop skips the farmers, truck drivers and workers who connect distant places. Correct the claim or use of sources, not just the neatness of the poster.","title":"Understand and model","visual":[{"alt":"A connected chain for bread.","caption":"Every link has a person and place.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Wheat</text><text x=\"28\" y=\"78\">farm, mill, bakery, shop</text><text x=\"358\" y=\"42\">Chain</text><text x=\"358\" y=\"78\">many people and places</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which source or place detail matters most.","who":"pip"},{"text":"Name the sources, map features or community examples that carry the idea before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Example: wheat grows on a farm, is trucked to a mill, becomes flour, is baked into bread at a bakery and is sold in a sh Then write your own evidence.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which source or place detail matters most.\nJuno: Name the sources, map features or community examples that carry the idea before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Example: wheat grows on a farm, is trucked to a mill, becomes flour, is baked into bread at a bakery and is sold in a sh Then write your own evidence."}}]},{"check":{"correct_index":0,"explanation":"Make the HSIE idea visible: name the observation, source or example you used and say why it supports the claim. Supported records follow the actual sources and purpose of the task.","options":["Make the HSIE idea visible: name the observation, source or example you used and say why it supports the claim.","A claim unrelated to the source or place.","An answer copied without understanding.","A guess with no evidence."],"question":"What should you demonstrate in this teaching stage?"},"example":"WORKED MODEL\nExample: wheat grows on a farm, is trucked to a mill, becomes flour, is baked into bread at a bakery and is sold in a shop. Many people in different places each do one step. If a flood closes a road, the next step is delayed. Look at each observation, source detail or example that carries the idea.\n\nTRY FIRST\nList the key observations, sources or steps from the model and say what each one shows.\n\nFEEDBACK\nThe most useful record names the evidence and the reason it supports the claim, not only a label.","explain":"Make the HSIE idea visible: name the observation, source or example you used and say why it supports the claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on sources, places and respectful community knowledge, rather than guessing from a single picture. Keep every claim linked to evidence.\n\nHOW TO WORK\nRead the worked example and name the sources, map features or community examples that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a detail is uncertain, identify what source you would need next. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Writing only a final label without evidence does not show HSIE thinking. Correct the claim or use of sources, not just the neatness of the poster.","title":"Show the evidence","visual":[{"alt":"Food moving between places.","caption":"If one link breaks, the chain stops.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Bananas</text><text x=\"28\" y=\"78\">Queensland farms</text><text x=\"358\" y=\"42\">Shops</text><text x=\"358\" y=\"78\">other states</text></g></svg>"}]},{"check":{"correct_index":0,"explanation":"Use an intentionally incorrect claim as a comparison. Name its specific HSIE error, then show the corrected evidence-based claim. Supported records follow the actual sources and purpose of the task.","options":["Use an intentionally incorrect claim as a comparison. Name its specific HSIE error, then show the corrected evidence-based claim.","A claim unrelated to the source or place.","An answer copied without understanding.","A guess with no evidence."],"question":"What should you demonstrate in this teaching stage?"},"example":"WORKED MODEL\nBelieving food comes from the shop skips the farmers, truck drivers and workers who connect distant places. Here is a more productive model: Example: wheat grows on a farm, is trucked to a mill, becomes flour, is baked into bread at a bakery and is sold in a shop. Many people in different places each do one step. If a flood closes a road, the next step is delayed.\n\nTRY FIRST\nDescribe why the warned-against claim fails, then write a corrected claim with evidence.\n\nFEEDBACK\nFor example: grown and picked on a farm; packed and trucked to a market; delivered to a shop and bought. Name the places and people at each step.","explain":"Use an intentionally incorrect claim as a comparison. Name its specific HSIE error, then show the corrected evidence-based claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on sources, places and respectful community knowledge, rather than guessing from a single picture. Keep every claim linked to evidence.\n\nHOW TO WORK\nRead the worked example and name the sources, map features or community examples that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a detail is uncertain, identify what source you would need next. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Changing the wording without repairing the evidence does not fix the error. Believing food comes from the shop skips the farmers, truck drivers and workers who connect distant places. Correct the claim or use of sources, not just the neatness of the poster.","title":"Test a misconception"},{"check":{"correct_index":0,"explanation":"Use the same HSIE idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence. Supported records follow the actual sources and purpose of the task.","options":["Use the same HSIE idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence.","A claim unrelated to the source or place.","An answer copied without understanding.","A guess with no evidence."],"question":"What should you demonstrate in this teaching stage?"},"example":"WORKED MODEL\nPeople and places are connected through the things they share and trade, such as food, goods, jobs and ideas. A product passes through many places and people before it reaches us, so places depend on each other. Now choose a different example to show you can transfer the idea.\n\nTRY FIRST\nInquire into or describe one fresh example that uses the same skill and write a short evidence-based reason.\n\nFEEDBACK\nThe new example should use the same HSIE idea as the model, but contain different evidence.","explain":"Use the same HSIE idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence.\n\nWHY IT MATTERS\nThis helps the learner base claims on sources, places and respectful community knowledge, rather than guessing from a single picture. Keep every claim linked to evidence.\n\nHOW TO WORK\nRead the worked example and name the sources, map features or community examples that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a detail is uncertain, identify what source you would need next. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new evidence. Correct the claim or use of sources, not just the neatness of the poster.","title":"Transfer to a new inquiry"}],"title":"Year 3, Week 20, Lesson 1: People and places connected","unit_number":4,"unit_title":"People and environments","week":20,"week_in_unit":5,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample: wheat grows on a farm, is trucked to a mill, becomes flour, is baked into bread at a bakery and is sold in a shop. Many people in different places each do one step. If a flood closes a road, the next step is delayed.\n\nWrite what makes this example accurate, naming the sources, places or community details used.","worked_visuals":[{"alt":"A connected chain for bread.","caption":"Every link has a person and place.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Wheat</text><text x=\"28\" y=\"78\">farm, mill, bakery, shop</text><text x=\"358\" y=\"42\">Chain</text><text x=\"358\" y=\"78\">many people and places</text></g></svg>"},{"alt":"Food moving between places.","caption":"If one link breaks, the chain stops.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Bananas</text><text x=\"28\" y=\"78\">Queensland farms</text><text x=\"358\" y=\"42\">Shops</text><text x=\"358\" y=\"78\">other states</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-hsie-y3-w20-l1' AND family_id IS NULL;
